const esc=value=>String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function registrationCard(task){return`<section class="registration-card" aria-label="掛號單"><div class="registration-header"><span>耳鼻喉科 · 門診</span><b>掛號單</b></div><span class="paper-small">姓名</span><strong class="registered-name">${esc(task.patient.name)}</strong><p>${task.patient.age} 歲 · 預約更換${task.caseId==='outpatientNG'?'鼻胃管':'氣切管'}</p><div class="registration-model"><span>本次管型</span><b>${esc(task.code)}</b></div><small>虛構病人 · 器材包裝為示意</small><div class="registration-barcode" aria-hidden="true"></div></section>`;}
export function tubePackage(pack,{opened=false}={}){
  const ng=pack.type==='outpatientNG',gradient='pack-'+pack.id.replace(/[^a-zA-Z0-9_-]/g,'-');return`<svg class="tube-package" viewBox="0 0 280 215" aria-hidden="true"><defs><linearGradient id="${gradient}" x2="1" y2="1"><stop stop-color="#f6f6ed"/><stop offset="1" stop-color="#b9cecc"/></linearGradient></defs><path d="M30 19 245 25 250 191 28 185Z" fill="url(#${gradient})" stroke="#8ba4a7"/><path d="M38 31 235 37 239 179 38 174Z" fill="#e2ece2" stroke="#bdcfc5"/><path d="M33 22 246 28M29 180 249 186" stroke="#afc1b4" stroke-width="5"/><rect x="47" y="42" width="175" height="25" rx="3" fill="#526f78"/><text x="134" y="60" text-anchor="middle" fill="#fff8e8" font-size="14">${esc(pack.id)}</text>${ng?'<path d="M181 86c-97-20-120 80-49 76s70-69 13-62-44 38-11 36 24-18 11-18" stroke="#a4bab3" stroke-width="9" fill="none"/><path d="M181 86c-97-20-120 80-49 76s70-69 13-62-44 38-11 36 24-18 11-18" stroke="#f2f1dc" stroke-width="5" fill="none"/><path d="M179 86h20v13h-20Z" fill="#8aa29a"/><path d="M133 164h23" stroke="#536e72" stroke-width="3"/>':'<path d="M101 89h37v27q0 21 34 24v23q-64-5-64-47Z" fill="#c2d7d0" stroke="#6e9699" stroke-width="3"/><path d="M93 103h54v23H93Z" fill="#7daba6" stroke="#557c83"/><ellipse cx="120" cy="114" rx="9" ry="17" fill="#e2eadd"/><ellipse cx="120" cy="114" rx="5" ry="11" fill="#4c6c77"/><path d="M173 138v26" stroke="#f2f2df" stroke-width="5"/><path d="M137 116q20-31 44-23" fill="none" stroke="#9ab6b2" stroke-width="3"/>'}<path d="M44 30 234 176M217 36 233 90" stroke="#fffef4" stroke-width="5" opacity=".35"/><text x="135" y="199" text-anchor="middle" fill="#4b6875" font-size="10">${opened?'已核對，準備就緒':'包裝標籤 · 核對後再選用'}</text></svg>`;
}
export function tubeDeskArt(task){return`<div class="tube-desk-scene"><svg viewBox="0 0 420 245" aria-hidden="true"><defs><linearGradient id="clinicWood"><stop stop-color="#c5a581"/><stop offset="1" stop-color="#947656"/></linearGradient></defs><rect width="420" height="245" rx="10" fill="#b8c6c4"/><path d="M0 114 420 75v170H0Z" fill="url(#clinicWood)"/><path d="M0 145 420 103M0 201 420 157" stroke="#927857" opacity=".4"/><path d="M40 107 190 99 211 208 59 219Z" fill="#eeeade" stroke="#b4b8ac"/><path d="M61 128 175 123M66 142l114-5M70 160l88-4M75 177l114-5" stroke="#98aaa5" stroke-width="3"/><path d="M69 113h74" stroke="#586f7b" stroke-width="4"/><rect x="252" y="22" width="125" height="89" rx="4" fill="#344d5b"/><path d="M260 31h109v69H260Z" fill="#93adad"/><path d="M273 48h82m-82 14h53m-53 14h72" stroke="#ccdad1" stroke-width="4"/><path d="M307 111v20h-28" stroke="#506674" stroke-width="8"/><path d="M234 140q-22-18-26 2t-8 45q-5 20-22 0" fill="none" stroke="#385b6b" stroke-width="5"/><circle cx="181" cy="187" r="13" fill="#bacbc6" stroke="#577983" stroke-width="4"/></svg><div class="desk-tube">${tubePackage({id:task.code,type:task.caseId})}</div><span class="desk-art-caption">小禾已把管子和掛號單放在工作桌上。</span></div>`;}
